{
  "items": [
    {
      "name": "MvPowerSeries.coeff",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_2} → [inst : Semiring R] → (σ →₀ ℕ) → MvPowerSeries σ R →ₗ[R] R"
    },
    {
      "name": "Polynomial.coeff_mul_X_pow'",
      "module_name": "Mathlib.Algebra.Polynomial.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R) (n d : ℕ),\n  (p * Polynomial.X ^ n).coeff d = if n ≤ d then p.coeff (d - n) else 0"
    },
    {
      "name": "Polynomial.coeff_X_pow_mul'",
      "module_name": "Mathlib.Algebra.Polynomial.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R) (n d : ℕ),\n  (Polynomial.X ^ n * p).coeff d = if n ≤ d then p.coeff (d - n) else 0"
    },
    {
      "name": "MvPolynomial.optionEquivLeft_coeff_some_coeff_none",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ (R : Type u) (S₁ : Type v) [inst : CommSemiring R] (n : Option S₁ →₀ ℕ) (f : MvPolynomial (Option S₁) R),\n  MvPolynomial.coeff n.some (((MvPolynomial.optionEquivLeft R S₁) f).coeff (n none)) = MvPolynomial.coeff n f"
    },
    {
      "name": "PowerSeries.coeff",
      "module_name": "Mathlib.RingTheory.PowerSeries.Basic",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → ℕ → PowerSeries R →ₗ[R] R"
    },
    {
      "name": "Polynomial.coeff",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Semiring R] → Polynomial R → ℕ → R"
    },
    {
      "name": "PowerSeries.coeff_mul_X_pow'",
      "module_name": "Mathlib.RingTheory.PowerSeries.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : PowerSeries R) (n d : ℕ),\n  (PowerSeries.coeff d) (p * PowerSeries.X ^ n) = if n ≤ d then (PowerSeries.coeff (d - n)) p else 0"
    },
    {
      "name": "Polynomial.coeff_X_pow_mul",
      "module_name": "Mathlib.Algebra.Polynomial.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R) (n d : ℕ), (Polynomial.X ^ n * p).coeff (d + n) = p.coeff d"
    }
  ]
}
